const { chromium } = require('D:/repository/苏住房防汛C端/node_modules/.bun/playwright@1.64.1/node_modules/playwright');
(async () => {
  const b = await chromium.launch({ executablePath: 'C:/Users/Administrator/AppData/Local/ms-playwright/chromium-1243/chrome-win64/chrome.exe' });
  const pg = await b.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  await pg.goto('http://127.0.0.1:8095/#/pages/data/index', { waitUntil: 'networkidle' });
  await pg.waitForTimeout(1500);
  const chips = await pg.$('.no-scrollbar');
  if (chips) { await pg.evaluate(el => el.scrollLeft = el.scrollWidth, chips); await pg.waitForTimeout(400); }
  await pg.screenshot({ path: 'data-shot-final.png' });
  console.log('horiz=' + (await pg.content()).includes('more_horiz'));
  await b.close();
})();
